// DeleteKubernetesRuntimeInstanceCmd represents the command 'tptctl delete kubernetes-runtime-instance'
var DeleteKubernetesRuntimeInstanceCmd = &cobra.Command{
	Example: "  # delete using a config file\n  tptctl delete kubernetes-runtime-instance --config path/to/config.yaml\n\n  # delete using name\n  tptctl delete kubernetes-runtime-instance --name some-kubernetes-runtime-instance",
	Long:    "Delete an existing kubernetes runtime instance.",
	PreRun:  CommandPreRunFunc,
	Run: func(cmd *cobra.Command, args []string) {
		apiClient, _, apiEndpoint, _ := GetClientContext(cmd)

		// flag validation
		if err := cli.ValidateConfigNameFlags(
			kubernetesRuntimeConfigPath,
			kubernetesRuntimeName,
			"kubernetes runtime instance",
		); err != nil {
			cli.Error("flag validation failed", err)
			os.Exit(1)
		}

		// delete kubernetes runtime instance based on version
		switch kubernetesRuntimeVersion {
		case "v0":
			var kubernetesRuntimeInstanceConfig config_v0.KubernetesRuntimeInstanceConfig
			if kubernetesRuntimeConfigPath != "" {
				// load kubernetes runtime instance config
				configContent, err := os.ReadFile(kubernetesRuntimeConfigPath)
				if err != nil {
					cli.Error("failed to read config file", err)
					os.Exit(1)
				}
				if err := yaml.UnmarshalStrict(configContent, &kubernetesRuntimeInstanceConfig); err != nil {
					cli.Error("failed to unmarshal config file yaml content", err)
					os.Exit(1)
				}
			} else {
				kubernetesRuntimeInstanceConfig = config_v0.KubernetesRuntimeInstanceConfig{
					KubernetesRuntimeInstance: config_v0.KubernetesRuntimeInstanceValues{
						Name: &kubernetesRuntimeName,
					},
				}
			}

			// delete kubernetes runtime instance
			deletedKubernetesRuntimeInstance, err := kubernetesRuntimeInstanceConfig.Delete(apiClient, apiEndpoint)
			if err != nil {
				cli.Error("failed to delete kubernetes runtime instance", err)
				os.Exit(1)
			}

			cli.Complete(fmt.Sprintf("kubernetes runtime instance %s deleted", *deletedKubernetesRuntimeInstance.KubernetesRuntimeInstance.Name))
		default:
			cli.Error("", errors.New("unrecognized object version"))
			os.Exit(1)
		}
	},
	Short:        "Delete an existing kubernetes runtime instance",
	SilenceUsage: true,
	Use:          "kubernetes-runtime-instance",
}

